import math

def solve_transport(demand_tonnes, elevator_capacity_tonnes, rocket_capacity_kg, rocket_cost, cost_per_tonne):
    rocket_tonnes = rocket_capacity_kg / 1000.0
    if rocket_tonnes <= 0.0 or rocket_cost <= 0.0 or demand_tonnes < 0.0 or elevator_capacity_tonnes < 0.0 or cost_per_tonne < 0.0:
        raise ValueError("valid capacities, demand, and nonnegative prices are required")
    min_launches = math.ceil(max(0.0, demand_tonnes - elevator_capacity_tonnes) / rocket_tonnes)
    max_launches = math.ceil(demand_tonnes / rocket_tonnes)
    best_cost = None
    plans = []
    for launches in range(min_launches, max_launches + 1):
        e_tonnes = max(0.0, demand_tonnes - launches * rocket_tonnes)
        if e_tonnes > elevator_capacity_tonnes:
            continue
        cost = cost_per_tonne * e_tonnes + rocket_cost * launches
        plan = {"e_tonnes": e_tonnes, "launches": launches, "cost": cost}
        if best_cost is None or cost < best_cost:
            best_cost = cost
            plans = [plan]
        elif math.isclose(cost, best_cost, rel_tol=1e-12, abs_tol=1e-9):
            plans.append(plan)
    return plans

